            if (!_ipValido(c.ip)) { erro("IP inválido: '" + c.ip + "'"); return; }
            if (!_inteiro(pos, 0, 4)) { erro('posição no nó tem de ser 0 a 4, veio ' + pos); return; }
            if (pos && !m.multidrive) { erro(m.nome + ' não tem Multi-Drive: posição tem de ser 0'); return; }
            chave = ['cip', c.ip, _padrao(c.porta, 44818), pos].join('|');
            desc = c.ip + ' posição ' + pos;
        } else if (tipo === 'tcp') {
            if (!_ipValido(c.ip)) { erro("IP inválido: '" + c.ip + "'"); return; }
            if (!_inteiro(_padrao(c.porta, 502), 1, 65535)) { erro('porta TCP inválida'); return; }
            if (!_inteiro(_padrao(c.endereco, 1), 1, 247)) { erro('endereço de escravo tem de ser 1 a 247'); return; }
            chave = ['tcp', c.ip, _padrao(c.porta, 502), _padrao(c.endereco, 1)].join('|');
            desc = c.ip + ' endereço ' + _padrao(c.endereco, 1);
        } else {
            ps = String(c.porta_serial || '').trim();
            if (!ps) { erro('porta serial vazia'); return; }
            if (!_inteiro(c.endereco, 1, 247)) { erro('endereço de escravo tem de ser 1 a 247'); return; }
            if ([9600, 19200, 38400].indexOf(_padrao(c.baud, 9600)) < 0) { erro('velocidade tem de ser 9600, 19200 ou 38400'); return; }
            if (['E', 'O', 'N'].indexOf(_padrao(c.paridade, 'E')) < 0) { erro('paridade tem de ser E, O ou N'); return; }
            ajuste = [_padrao(c.baud, 9600), _padrao(c.paridade, 'E')];
            const b = barramentos[ps];
            if (b && (b.ajuste[0] !== ajuste[0] || b.ajuste[1] !== ajuste[1])) {
                erro(ps + ' já está em ' + b.ajuste[0] + ' ' + b.ajuste[1] + ' (por causa de ' + b.id +
                     '); todos os drives de um barramento têm de usar a mesma velocidade e paridade');
                return;
            }
            chave = ['rtu', ps, c.endereco].join('|');
            desc = ps + ' endereço ' + c.endereco;
        }
        if (posicoes[chave]) { erro(desc + ' já é usado por ' + posicoes[chave]); return; }
        if (tipo === 'rtu' && !barramentos[ps]) { barramentos[ps] = { ajuste: ajuste, id: iid }; }
        ids[iid] = true;
        posicoes[chave] = iid;
        validos.push(it);
    });
    return { validos: validos, erros: erros };
}

// Onde o drive esta, em uma linha: para a lista e para as mensagens.
function descreverConexao(it) {
    const c = (it && it.conexao) || {};
    if (c.tipo === 'cip') {
        const pos = _padrao(c.posicao, 0);
        return c.ip + (pos ? '  ·  drive ' + pos + ' (DSI)' : '  ·  drive 0 (Ethernet)');
    }
    if (c.tipo === 'tcp') { return c.ip + ':' + _padrao(c.porta, 502) + '  ·  endereço ' + _padrao(c.endereco, 1); }
    if (c.tipo === 'rtu') {
        return c.porta_serial + '  ·  endereço ' + c.endereco + '  ·  ' + _padrao(c.baud, 9600) + ' ' + _padrao(c.paridade, 'E');
    }
    return '';
}
// ===== fim do validador =====


// Aplica a acao da tela, VALIDA A LISTA INTEIRA com o mesmo validador da
// tela e so entao grava. Saidas: 1 = arquivo, 2 = resposta para a tela,
// 3 = redesenha a tela na hora (sem esperar o ciclo de 3 s).
const p = msg.payload || {};
let lista = JSON.parse(JSON.stringify(flow.get('inversores_cfg') || []));
const resp = function (ok, texto) {
    return { payload: { resposta: { ok: ok, texto: texto, pedido: p.pedido } } };
};

// Diagnostico (usado pelos testes): so valida, nao grava.
if (p.acao === 'validar') {
    return [null, { payload: { validacao: validarInversores({ inversores: p.inversores || [] }) } }, null];
}

let texto;
if (p.acao === 'salvar') {
    const it = normalizarItem(p.item || {});
    const outros = lista.filter(function (i) { return i.id !== p.original; });
    // O id nasce uma vez e nunca muda: e ele que o cadastro de ativos usa.
    if (p.original) { it.id = p.original; }
    else if (!it.id || outros.some(function (i) { return i.id === it.id; })) {
        it.id = gerarIdInversor(outros, it.tag, it.nome, it.modelo);
    }
    // Campo que a tela nao edita (intervalo_s) sobrevive a uma edicao.
    const antigo = lista.find(function (i) { return i.id === p.original; });
    if (antigo && antigo.intervalo_s !== undefined && it.intervalo_s === undefined) {
        it.intervalo_s = antigo.intervalo_s;
    }
    const nova = p.original
        ? lista.map(function (i) { return i.id === p.original ? it : i; })
        : lista.concat([it]);
    // Valida com o item que MUDOU no FIM da lista: o validador percorre em
    // ordem, e quem vem primeiro fica com o lugar. Com o item editado no
    // meio da lista, um conflito seria atribuido ao VIZINHO -- e o gateway
    // passaria a recusar o drive que estava funcionando, sem aviso nenhum.
    // A ordem gravada continua a original.
    const meus = validarInversores({ inversores: outros.concat([it]) }).erros
        .filter(function (e) { return e.id === it.id; }).map(function (e) { return e.erro; });
    if (meus.length) { return [null, resp(false, 'Não salvo: ' + meus.join('; ')), null]; }
    lista = nova;
    texto = (p.original ? 'Alterações salvas' : 'Inversor adicionado') + ' — o gateway aplica em segundos.';
} else if (p.acao === 'remover') {
    if (!lista.some(function (i) { return i.id === p.id; })) { return [null, resp(false, 'Inversor não encontrado.'), null]; }
    lista = lista.filter(function (i) { return i.id !== p.id; });
    // Continua associado a um ativo? Avisa -- remover a associacao e
    // decisao de quem cuida do cadastro de ativos, nao desta tela.
    const cad = flow.get('cadastro') || {};
    let onde = '';
    Object.keys(cad).forEach(function (a) {
        const partes = (cad[a] || {}).partes || {};
        Object.keys(partes).forEach(function (pn) {
            if ((partes[pn] || {}).inversor === p.id) { onde = a + ' › ' + pn; }
        });
    });
    texto = 'Inversor removido.' + (onde ? ' Ele continua associado a ' + onde + ' em Configuração.' : '');
} else if (p.acao === 'habilitar') {
    const nova = lista.map(function (i) {
        return i.id === p.id ? Object.assign({}, i, { habilitado: !!p.habilitado }) : i;
    });
    if (p.habilitado) {
        // Religar pode conflitar com quem ocupou o lugar enquanto ele
        // estava desligado.
        // Mesmo cuidado do salvar: o religado vai para o fim na validacao.
        const alvo = nova.filter(function (x) { return x.id === p.id; });
        const resto = nova.filter(function (x) { return x.id !== p.id; });
        const e = validarInversores({ inversores: resto.concat(alvo) }).erros.filter(function (x) { return x.id === p.id; });
        if (e.length) { return [null, resp(false, 'Não ligado: ' + e.map(function (x) { return x.erro; }).join('; ')), null]; }
    }
    lista = nova;
    texto = p.habilitado ? 'Leitura ligada.' : 'Leitura desligada.';
} else {
    return [null, null, null];
}

flow.set('inversores_cfg', lista);
const arquivo = {
    filename: (env.get('IOT_DADOS') || '/opt/iot/dados') + '/inversores.json',
    payload: JSON.stringify({ versao: 1, inversores: lista }, null, 2) + '\n'
};
return [arquivo, resp(true, texto), { payload: 'redesenhar' }];

// Fecha a janela de agregacao e emite as linhas para o banco.
//
// O acumulador e alimentado pela ingestao (ver "registrar telemetria" e
// "registrar corrente"). Aqui so consolidamos e zeramos.

const acc = flow.get('acumulador') || {};
flow.set('acumulador', {});          // zera JA: o campo continua chegando

const cadastro = flow.get('cadastro') || {};

// Onde cada device_id estava alocado NESTE momento. Guardado junto da
// medicao para a historia antiga continuar verdadeira se o sensor for
// remanejado depois.
const onde = {};
for (const tag of Object.keys(cadastro)) {
    const partes = (cadastro[tag] || {}).partes || {};
    for (const nome of Object.keys(partes)) {
        const pt = partes[nome] || {};
        if (pt.esp32)    { onde[pt.esp32]    = { ativo: tag, parte: nome }; }
        if (pt.inversor) { onde[pt.inversor] = { ativo: tag, parte: nome }; }
    }
}

const estados = flow.get('estados_por_device') || {};
const linhas = [];

for (const id of Object.keys(acc)) {
    const a = acc[id];
    if (!a.n) { continue; }                    // janela sem leitura nenhuma

    function med(x) { return x.n ? x.soma / x.n : null; }
    const loc = onde[id] || {};

    // Canais que so passaram a existir depois: um acumulador antigo,
    // sobrevivente de deploy, nao os tem.
    const vel = a.vel || { n: 0 };
    const cri = a.crista || { n: 0 };

    linhas.push([
        new Date(a.ate).toISOString(),
        id,
        loc.ativo || null,
        loc.parte || null,
        a.n,
        med(a.temp), a.temp.n ? a.temp.min : null, a.temp.n ? a.temp.max : null,
        med(a.vib),  a.vib.n  ? a.vib.min  : null, a.vib.n  ? a.vib.max  : null,
        med(vel),    vel.n ? vel.max : null,
        med(cri),    cri.n ? cri.max : null,
        med(a.corr), a.corr.n ? a.corr.min : null, a.corr.n ? a.corr.max : null,
        med(a.tensao), med(a.dcbus), med(a.freq),
        (a.rodando === undefined) ? null : a.rodando,
        estados[id] || null,
        false                                  // recuperada: esta e ao vivo
    ]);
}

// ---- Amostras recuperadas do buffer do ESP32 -------------------------
// Nao passam pelo acumulador: cada uma ja e uma medicao unica, com o
// instante em que foi COLHIDA (reconstruido de atraso_ms). Agrega-las na
// janela de agora jogaria o passado todo no minuto atual e destruiria
// justamente a informacao que o buffer existe para preservar.
//
// media = min = max = o proprio valor, e amostras = 1: e literalmente o
// que se sabe. E 'estado' fica nulo porque nao houve avaliacao ao vivo
// naquele instante -- inventar um agora seria julgar o passado com o
// cadastro de hoje.
const fila = flow.get('backfill') || [];
if (fila.length) {
    const MAX_LOTE = 500;      // nao estourar o limite de parametros do PG
    const lote = fila.splice(0, MAX_LOTE);
    flow.set('backfill', fila);

    for (const b of lote) {
        const loc = onde[b.device_id] || {};
        linhas.push([
            new Date(b.ts).toISOString(),
            b.device_id,
            loc.ativo || null,
            loc.parte || null,
            1,
            // ?? null porque undefined (campo que o firmware antigo nao
            // manda) vira erro de parametro no driver do PostgreSQL.
            b.temperatura_c ?? null, b.temperatura_c ?? null, b.temperatura_c ?? null,
            b.vib_rms_g ?? null, b.vib_rms_g ?? null, b.vib_rms_g ?? null,
            b.vib_vel_mm_s ?? null, b.vib_vel_mm_s ?? null,
            b.vib_crista ?? null, b.vib_crista ?? null,
            null, null, null,
            null, null, null,
            null,
            null,
            true                               // recuperada
        ]);
    }
    node.warn('backfill: gravando ' + lote.length + ' amostras recuperadas'
              + (fila.length ? ' (faltam ' + fila.length + ')' : ''));
}

if (!linhas.length) { return [null, null]; }

// INSERT em lote com um unico comando: uma ida ao banco por janela, e
// nao uma por dispositivo.
// Derivado do proprio dado, e nao um numero escrito a mao: a contagem
// errada (18 para 19 colunas) desalinha os $n a partir da segunda linha e
// so aparece quando ha mais de um dispositivo -- ou seja, nunca no teste
// simples, sempre em producao.
const cols = linhas[0].length;
const valores = linhas.map(function (_, i) {
    const base = i * cols;
    const ph = [];
    for (let k = 1; k <= cols; k++) { ph.push('$' + (base + k)); }
    return '(' + ph.join(',') + ')';
}).join(',');

const m_med = {
    query: 'INSERT INTO medicoes (ts, device_id, ativo, parte, amostras,' +
           ' temperatura_c, temperatura_min_c, temperatura_max_c,' +
           ' vibracao_rms_g, vibracao_min_g, vibracao_max_g,' +
           ' vibracao_vel_mm_s, vibracao_vel_max_mm_s,' +
           ' vibracao_crista, vibracao_crista_max,' +
           ' corrente_a, corrente_min_a, corrente_max_a,' +
           ' tensao_v, dc_bus_v, frequencia_hz, rodando, estado, recuperada)' +
           ' VALUES ' + valores,
    params: [].concat.apply([], linhas)
};

// ---- Eventos: grava os que abriram e fecha os que terminaram ---------
const hist = flow.get('historico_alarmes') || [];
const gravados = flow.get('eventos_gravados') || {};
const cmds = [];

for (const h of hist) {
    const ja = gravados[h.chave + '@' + h.inicio_ms];
    if (!ja) {
        cmds.push({
            query: 'INSERT INTO eventos (inicio, fim, device_id, ativo, parte,' +
                   ' estado, motivo) VALUES ($1,$2,$3,$4,$5,$6,$7)',
            params: [new Date(h.inicio_ms).toISOString(),
                     h.fim_ms ? new Date(h.fim_ms).toISOString() : null,
                     null, h.ativo, h.parte, h.estado, h.motivos.join(' | ')]
        });
        gravados[h.chave + '@' + h.inicio_ms] = h.fim_ms ? 'fechado' : 'aberto';
    } else if (ja === 'aberto' && h.fim_ms) {
        // Fecha pelo par (inicio, ativo, parte): sem id proprio no lado do
        // fluxo, e o que identifica a linha sem ambiguidade.
        cmds.push({
            query: 'UPDATE eventos SET fim = $1 WHERE inicio = $2' +
                   ' AND ativo IS NOT DISTINCT FROM $3' +
                   ' AND parte IS NOT DISTINCT FROM $4 AND fim IS NULL',
            params: [new Date(h.fim_ms).toISOString(),
                     new Date(h.inicio_ms).toISOString(), h.ativo, h.parte]
        });
        gravados[h.chave + '@' + h.inicio_ms] = 'fechado';
    }
}
// Nao deixa o mapa crescer sem limite junto com o historico.
const chaves = Object.keys(gravados);
if (chaves.length > 400) {
    const novo = {};
    chaves.slice(-200).forEach(function (k) { novo[k] = gravados[k]; });
    flow.set('eventos_gravados', novo);
} else {
    flow.set('eventos_gravados', gravados);
}

// Varias mensagens numa saida = o proprio array, sem envolver de novo.
// Com [cmds] o Node-RED recebe um array DENTRO do array de saidas e
// recusa: "Function tried to send a message of type Array".
return [m_med, cmds.length ? cmds : null];

// Manda para o ativo ABERTO na tela, em vez de um id fixo no codigo.
//
// A chave pode ser um device_id ("motor-01", descoberta automatica) ou uma
// TAG do cadastro ("U1", "U1/Motor principal"). O comando so faz sentido
// para um ESP32 de verdade, entao quem resolve isso e o registro publicado
// pelo renderizador.
//
// Saida 0 -> MQTT.  Saida 1 -> aviso na tela.
function aviso(txt, cor) {
    return [null, { payload: txt, ui_update: { colorDefault: cor } }];
}

const chave = flow.get('ativo_sel');
if (!chave) { return aviso('Nenhum ativo aberto.', 'warning'); }

const destinos = (flow.get('esp32_por_chave') || {})[chave] || [];
if (!destinos.length) {
    return aviso('"' + chave + '" nao tem modulo conhecido para comandar.',
                 'warning');
}

// Numero = intervalo (dropdown). String = acao (botoes). Objeto com
// .identificar = piscar UM modulo especifico (clique na lista).
const p = msg.payload;
let corpo = null;
let texto = '';

// Identificar e o unico comando que NAO vai para todos: mandar os dois
// modulos piscarem juntos anula a funcao de descobrir qual e qual.
if (p && typeof p === 'object' && p.identificar) {
    const alvo = String(p.identificar);
    if (destinos.indexOf(alvo) < 0) {
        return aviso('"' + alvo + '" nao pertence a este ativo.', 'warning');
    }
    return [[{ topic: 'monitoramento/' + alvo + '/cmd',
               payload: JSON.stringify({ comando: 'identificar', seg: 15 }) }],
            { payload: 'Piscando ' + alvo + ' por 15 s — procure o modulo',
              ui_update: { colorDefault: 'info' } }];
}

if (typeof p === 'number') {
    corpo = { intervalo_ms: p };
    texto = 'Intervalo de publicacao: ' + (p / 1000) + ' s';

} else if (p === 'publicar') {
    corpo = { comando: 'publicar' };
    texto = 'Leitura imediata solicitada';

} else if (p === 'reiniciar') {
    // Confirmacao em dois cliques. Reiniciar cria buraco no historico, e um
    // toque acidental na tela do painel de campo nao pode derrubar um no.
    // Sem widget extra: o proprio botao arma e, no segundo clique dentro da
    // janela, executa.
    const agora = Date.now();
    const armado = flow.get('reinicio_armado') || 0;
    if (agora - armado > 5000) {
        flow.set('reinicio_armado', agora);
        return aviso('Clique de novo em 5 s para confirmar o reinicio.',
                     'warning');
    }
    flow.set('reinicio_armado', 0);
    corpo = { comando: 'reiniciar' };
    texto = 'Reiniciando o modulo...';

} else {
    return aviso('Comando desconhecido.', 'warning');
}

// Um ativo principal com varias partes dispara em todas elas. O array
// vem aninhado de proposito: assim as N mensagens saem PELA MESMA saida.
const msgs = destinos.map(function (dev) {
    return { topic: 'monitoramento/' + dev + '/cmd',
             payload: JSON.stringify(corpo) };
});

const alvo = destinos.length > 1
             ? ' (' + destinos.length + ' modulos)'
             : '';
return [msgs, { payload: texto + alvo, ui_update: { colorDefault: 'info' } }];

format:
/* InsightX -- linguagem visual do simulador. Gerado por nodered/estilo.py */
:root {
  --ix-fundo: #0e1116; --ix-sup: #161b22; --ix-sup-2: #1c232c;
  --ix-borda: #2a323c; --ix-linha: #222a33;
  --ix-tinta: #e6edf3; --ix-tinta-2: #8b98a5; --ix-tinta-4: #5c6773;
  --ix-destaque: #2f81f7; --ix-destaque-suave: rgba(47,129,247,.14);
  --ix-raio: 10px;
  --ix-fonte: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

/* Fonte: a do sistema, como no simulador (o padrao era Helvetica). */
body, .v-application, .v-application .text-body-1, .v-application .text-h6,
.v-btn, .v-field, .v-list-item-title, .v-toolbar-title, .v-card-title {
  font-family: var(--ix-fonte) !important;
}
body, .v-application { background: var(--ix-fundo) !important; }
.nrdb-ui-widget { font-variant-numeric: tabular-nums; }

/* Cabecalho: sem sombra, uma linha fina embaixo -- como o do simulador. */
.v-app-bar {
  background: var(--ix-fundo) !important;
  border-bottom: 1px solid var(--ix-borda) !important;
  box-shadow: none !important;
}
.v-app-bar .v-toolbar__content { font-weight: 650; letter-spacing: -.01em; }

/* Menu lateral */
.v-navigation-drawer {
  background: var(--ix-sup) !important;
  border-right: 1px solid var(--ix-borda) !important;
}
.v-navigation-drawer .v-list-item { border-radius: 8px !important; }
.v-navigation-drawer .v-list-item--active { color: var(--ix-destaque) !important; }
.v-navigation-drawer .v-list-item--active > .v-list-item__overlay {
  background: var(--ix-destaque) !important; opacity: .14 !important;
}

/* Grupos = os cartoes do simulador: superficie, borda fina, titulo discreto */
.nrdb-ui-group > .v-card {
  background: var(--ix-sup) !important;
  border: 1px solid var(--ix-borda) !important;
  border-radius: var(--ix-raio) !important;
  box-shadow: none !important;
}
.nrdb-ui-group > .v-card > .v-card-item .v-card-title {
  font-size: 13px !important; font-weight: 600 !important;
  color: var(--ix-tinta-2) !important; letter-spacing: .01em;
}

/* Tabelas no estilo do registro do simulador: cabecalho apagado, linhas
   finas, numeros alinhados. */
.v-table.nrdb-table, .nrdb-ui-table .v-table { background: transparent !important; }
.v-data-table th, .v-data-table .v-data-table__th {
  color: var(--ix-tinta-4) !important; font-weight: 500 !important;
  font-size: 12px !important; text-transform: none !important;
  border-bottom: 1px solid var(--ix-borda) !important;
}
.v-data-table tbody td {
  font-size: 13px !important; color: var(--ix-tinta) !important;
  border-bottom: 1px solid var(--ix-linha) !important;
}
.v-data-table tbody tr:hover td { background: var(--ix-sup-2) !important; }

/* Botoes e campos */
.nrdb-ui-button .v-btn, .nrdb-ui-group .v-btn--variant-flat {
  text-transform: none !important; letter-spacing: 0 !important;
  border-radius: 8px !important; font-weight: 600 !important;
}
.v-field { border-radius: 8px !important; }
.v-field--variant-outlined .v-field__outline { color: var(--ix-borda) !important; --v-field-border-opacity: 1; }
.v-field--focused .v-field__outline { color: var(--ix-destaque) !important; }

/* Barra de rolagem discreta */
* { scrollbar-width: thin; scrollbar-color: var(--ix-borda) transparent; }
